mapper.select:
SELECT id, server_id AS serverId, tool_name AS toolName, qualified_name AS qualifiedName, display_name AS displayName, description, input_schema AS inputSchema, output_schema AS outputSchema, annotations_json AS annotationsJson, meta_json AS metaJson, schema_digest AS schemaDigest, source_type AS sourceType, discovery_status AS discoveryStatus, admin_enabled AS adminEnabled, general_chat_enabled AS generalChatEnabled, risk_level AS riskLevel, require_confirmation AS requireConfirmation, timeout_seconds AS timeoutSeconds, visible_result_fields AS visibleResultFields, last_discovered_at AS lastDiscoveredAt, create_time AS createTime, update_time AS updateTime FROM mcp_tool_info
AND del_flag = 0
AND server_id = #{bo.serverId}
AND (tool_name LIKE CONCAT('%', #{bo.toolName}, '%') OR display_name LIKE CONCAT('%', #{bo.toolName}, '%') OR qualified_name LIKE CONCAT('%', #{bo.toolName}, '%'))
AND qualified_name LIKE CONCAT('%', #{bo.qualifiedName}, '%')
AND risk_level = #{bo.riskLevel}
AND admin_enabled = #{bo.adminEnabled}
AND discovery_status = #{bo.discoveryStatus}
ORDER BY server_id ASC, qualified_name ASC, id ASC

